  return f'<label>{L("Your text","النص")}<textarea id="text-input" class="large-text" placeholder="{L("Paste your text here…","الصق النص هنا…")}"></textarea></label><div class="format-actions">'+''.join(f'<button class="secondary" data-format="{k}">{L(en,an)}</button>' for k,en,an in [('upper','UPPERCASE','أحرف كبيرة'),('lower','lowercase','أحرف صغيرة'),('title','Title Case','أحرف بداية كبيرة'),('spaces','Trim extra spaces','إزالة المسافات الزائدة'),('blank','Remove blank lines','حذف الأسطر الفارغة'),('list','Make a list','تحويل إلى قائمة'),('dedupe','Remove duplicate lines','إزالة الأسطر المكررة')])+f'</div><div class="actions">{btn}<button id="undo" class="secondary" disabled>{L("Undo","تراجع")}</button></div>'
