 schema=json.dumps({'@context':'https://schema.org','@type':'WebApplication','name':title,'applicationCategory':'UtilitiesApplication','operatingSystem':'Any','inLanguage':lang,'offers':{'@type':'Offer','price':'0','priceCurrency':'USD'}},ensure_ascii=False) if tool else ''
